def solve(grid):
    """
    Transform the input grid according to the discovered rule.

    The input contains a wall colour (the non‑zero colour that forms a regular
    rectangular network).  The walls may have a few gaps (zeroes on positions
    that should belong to a wall).  All other cells are interior cells that are
    grouped into rectangular rooms delimited by the walls.

    The output keeps the wall colour unchanged.  Every gap is painted with colour
    4.  Every interior room is painted uniformly:
        – colour 4 if the room touches at least one gap on any of its four
          sides (top, bottom, left, right);
        – colour 3 otherwise.
    """
    if not grid:
        return grid

    h = len(grid)
    w = len(grid[0])

    # ------------------------------------------------------------
    # 1. identify the wall colour
    from collections import Counter
    cnt = Counter()
    for row in grid:
        for v in row:
            if v != 0:
                cnt[v] += 1
    wall_colour = cnt.most_common(1)[0][0]

    # ------------------------------------------------------------
    # 2. locate wall rows and wall columns (they contain many wall_colour cells)
    def is_wall_line(length, get_value):
        # a line (row or column) is a wall if at least half of its cells are wall_colour
        wall = sum(1 for i in range(length) if get_value(i) == wall_colour)
        return wall * 2 >= length

    wall_rows = [r for r in range(h) if is_wall_line(w, lambda c: grid[r][c])]
    wall_cols = [c for c in range(w) if is_wall_line(h, lambda r: grid[r][c]))]

    wall_rows.sort()
    wall_cols.sort()

    # ------------------------------------------------------------
    # 3. build interior row / column intervals (the rooms)
    row_intervals = []
    start = 0
    for wr in wall_rows:
        if start <= wr - 1:
            row_intervals.append((start, wr - 1))
        start = wr + 1
    if start <= h - 1:
        row_intervals.append((start, h - 1))

    col_intervals = []
    start = 0
    for wc in wall_cols:
        if start <= wc - 1:
            col_intervals.append((start, wc - 1))
        start = wc + 1
    if start <= w - 1:
        col_intervals.append((start, w - 1))

    # map each interior cell to its room index
    row_of = [-1] * h
    for i, (r0, r1) in enumerate(row_intervals):
        for r in range(r0, r1 + 1):
            row_of[r] = i

    col_of = [-1] * w
    for j, (c0, c1) in enumerate(col_intervals):
        for c in range(c0, c1 + 1):
            col_of[c] = j

    # ------------------------------------------------------------
    # 4. locate all gaps (zeroes that lie on a wall line)
    gaps = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 and (r in wall_rows or c in wall_cols):
                gaps.add((r, c))

    # ------------------------------------------------------------
    # 5. decide the colour of each room
    room_colour = {}
    for i, (r0, r1) in enumerate(row_intervals):
        for j, (c0, c1) in enumerate(col_intervals):
            # check the four possible neighbours
            has_gap = False

            # top side
            if i > 0:
                top_wall = wall_rows[i - 1]
                for cc in range(c0, c1 + 1):
                    if (top_wall, cc) in gaps:
                        has_gap = True
                        break
            # bottom side
            if not has_gap and i < len(wall_rows):
                bottom_wall = wall_rows[i]
                for cc in range(c0, c1 + 1):
                    if (bottom_wall, cc) in gaps:
                        has_gap = True
                        break
            # left side
            if not has_gap and j > 0:
                left_wall = wall_cols[j - 1]
                for rr in range(r0, r1 + 1):
                    if (rr, left_wall) in gaps:
                        has_gap = True
                        break
            # right side
            if not has_gap and j < len(wall_cols):
                right_wall = wall_cols[j]
                for rr in range(r0, r1 + 1):
                    if (rr, right_wall) in gaps:
                        has_gap = True
                        break

            room_colour[(i, j)] = 4 if has_gap else 3

    # ------------------------------------------------------------
    # 6. build the output grid
    out = [[0] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == wall_colour:
                out[r][c] = wall_colour
            elif (r, c) in gaps:
                out[r][c] = 4
            else:
                ri = row_of[r]
                ci = col_of[c]
                # if ri or ci is -1 something is wrong, but grids are consistent
                out[r][c] = room_colour[(ri, ci)]

    return out

